create table service_calendars(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,owner_id int not null references users,name text not null,scope text not null check(scope in ('personal','shared')),member_ids int[] not null default '{}',provider text not null default 'local' check(provider in ('local','google','apple')),google_calendar_id text not null default 'primary',refresh_secret text,oauth_nonce text,oauth_expires timestamptz,created_at timestamptz not null default now());
create table service_appointments(id uuid primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,calendar_id int not null references service_calendars,conversation_id int not null references conversations,contact_id int not null references contacts,created_by int not null references users,responsible_id int not null references users,title text not null,starts_at timestamptz not null,ends_at timestamptz not null,time_zone text not null,status text not null default 'scheduled' check(status in ('scheduled','completed','absent','cancelled')),sync_state text not null default 'local' check(sync_state in ('local','pending','synced','error')),external_id text,notification_state text not null default 'pending' check(notification_state in ('pending','sending','sent','check_required')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create index service_appointments_range on service_appointments(tenant_id,calendar_id,responsible_id,starts_at,ends_at);
alter table service_calendars enable row level security;alter table service_calendars force row level security;
create policy tenant_iso on service_calendars using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int);
alter table service_appointments enable row level security;alter table service_appointments force row level security;
create policy tenant_iso on service_appointments using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int);
create trigger fk_guard before insert or update on service_calendars for each row execute function fk_guard('users','owner_id');
create trigger fk_guard before insert or update on service_appointments for each row execute function fk_guard('service_calendars','calendar_id','conversations','conversation_id','contacts','contact_id','users','created_by','users','responsible_id');
